function utf8Bytes(text) {
  let bytes = 0;
  for (let i = 0; i < text.length; i++) {
    const unit = text.charCodeAt(i);
    if (unit < 0x80) bytes++;
    else if (unit < 0x800) bytes += 2;
    else if (unit >= 0xd800 && unit <= 0xdbff) {
      const low = text.charCodeAt(++i);
      if (!(low >= 0xdc00 && low <= 0xdfff)) throw new Error('invalid-text-encoding');
      bytes += 4;
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      throw new Error('invalid-text-encoding');
    } else bytes += 3;
  }
  return bytes;
}

function viewHandle(value) {
  if (!value || typeof value.viewId !== 'string' || !value.viewId ||
      !Number.isSafeInteger(value.revision) || value.revision < 1) {
    throw new Error('invalid-view-handle');
  }
  return value;
}

export async function inspect(input, api) {
  const initial = viewHandle(await api.ui.present({ view: {
    title: '文本检查',
    blocks: [{ type: 'status', tone: 'info', text: '正在计算输入文本。' }],
    actions: []
  } }));

  const text = input.text;
  const parts = text.split(/\r\n|\n|\r/);
  const lines = text.length === 0 ? 0 : parts.length - (parts[parts.length - 1] === '' ? 1 : 0);
  const bytes = utf8Bytes(text);
  const trimmed = text.trim();
  const segments = trimmed ? trimmed.split(/\s+/u).length : 0;
  const previewCharacters = Array.from(text);
  const preview = previewCharacters.slice(0, 400).join('');
  const summary = [
    '文本检查',
    '文本行数：' + lines,
    'UTF-8 字节数：' + bytes + ' B',
    '空白分隔片段：' + segments,
    '', '原文：', text
  ].join('\n');

  const finalView = {
    title: '文本检查结果',
    blocks: [
      { type: 'fields', items: [
        { label: '文本行数', value: String(lines) },
        { label: 'UTF-8 字节数', value: String(bytes) + ' B' },
        { label: '空白分隔片段', value: String(segments) }
      ] },
      { type: 'code', language: 'text', code: preview },
      { type: 'text', text: 'CRLF、LF、CR 均计为换行，末尾换行不额外增加空行。片段按空白分隔，不做中文分词。'
        + (previewCharacters.length > 400 ? '原文预览仅显示前 400 个字符；草稿参数保留完整原文。' : '原文预览已完整显示。') },
      { type: 'status', tone: 'success', text: '本地统计已完成，没有调用模型或读取项目。' }
    ],
    actions: [{ id: 'prepare-note', label: '整理为草稿', actionId: 'prepare-draft', inputJson: JSON.stringify({ summary }) }]
  };
  const updated = viewHandle(await api.ui.update({ viewId: initial.viewId, revision: initial.revision, view: finalView }));
  if (updated.viewId !== initial.viewId || updated.revision !== initial.revision + 1) throw new Error('invalid-view-update');
  return { lines, bytes, segments, summary: '统计已完成。可选择“整理为草稿”，检查或修改参数后再运行。' };
}

export async function prepareDraft(input, api) {
  await api.draft.append({ text: input.summary });
  return '草稿已准备。点击“追加到草稿”后才会写入编辑区。';
}
